#include <algorithm>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace
{
    bool isJsSpace(char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r'; }

    int digitValue(char c)
    {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'z') return c - 'a' + 10;
        if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
        return 99;
    }
}

std::optional<double> jsParseInt(std::string_view s, std::optional<int> radix = std::nullopt)
{
    std::size_t i{ 0 };
    while (i < s.size() && isJsSpace(s[i])) ++i;
    double sign{ 1 };
    if (i < s.size() && (s[i] == '-' || s[i] == '+'))
    {
        if (s[i] == '-') sign = -1;
        ++i;
    }
    int r{ radix.value_or(0) };
    bool stripPrefix{ true };
    if (r != 0)
    {
        if (r < 2 || r > 36) return std::nullopt;
        if (r != 16) stripPrefix = false;
    }
    else
    {
        r = 10;
    }
    if (stripPrefix && i + 1 < s.size() && s[i] == '0' && (s[i + 1] == 'x' || s[i + 1] == 'X'))
    {
        i += 2;
        r = 16;
    }
    double value{ 0 };
    bool any{ false };
    for (; i < s.size(); ++i)
    {
        const int d{ digitValue(s[i]) };
        if (d >= r) break;
        value = value * r + d;
        any = true;
    }
    if (!any) return std::nullopt;
    return sign * value;
}

std::vector<int> jsDefaultSort(std::vector<int> values)
{
    std::stable_sort(values.begin(), values.end(),
        [](int a, int b) { return std::to_string(a) < std::to_string(b); });
    return values;
}

