bool is(const std::optional<double>& r, double v) { return r.has_value() && *r == v; }
TEST("reading digits until they stop") {
    CHECK(is(jsParseInt("42"), 42));
    CHECK(is(jsParseInt("  42px"), 42));
    CHECK(is(jsParseInt("1e3"), 1));
    CHECK(is(jsParseInt("12.9"), 12));
    CHECK(is(jsParseInt("\t\n-17 apples"), -17));
    CHECK(is(jsParseInt("+7"), 7));
    CHECK(is(jsParseInt("08"), 8));
}
TEST("radix and the 0x prefix") {
    CHECK(is(jsParseInt("0x1A"), 26));
    CHECK(is(jsParseInt("-0XfF"), -255));
    CHECK(is(jsParseInt("0x1A", 16), 26));
    CHECK(is(jsParseInt("1A", 16), 26));
    CHECK(is(jsParseInt("0x1A", 10), 0));
    CHECK(is(jsParseInt("0x1A", 0), 26));
    CHECK(is(jsParseInt("z", 36), 35));
    CHECK(is(jsParseInt("101", 2), 5));
    CHECK(is(jsParseInt("1012", 2), 5));
    CHECK(is(jsParseInt("777", 8), 511));
}
TEST("not a number") {
    CHECK(!jsParseInt("").has_value());
    CHECK(!jsParseInt("   ").has_value());
    CHECK(!jsParseInt("-").has_value());
    CHECK(!jsParseInt("px42").has_value());
    CHECK(!jsParseInt("0x").has_value());
    CHECK(!jsParseInt("12", 1).has_value());
    CHECK(!jsParseInt("12", 37).has_value());
    CHECK(!jsParseInt("2", 2).has_value());
    CHECK(!jsParseInt("- 5").has_value());
}
TEST("the default sort compares text") {
    CHECK(jsDefaultSort({ 10, 9, 1 }) == (std::vector<int>{ 1, 10, 9 }));
    CHECK(jsDefaultSort({ 10, 9, 1, 100, -1, 25 }) == (std::vector<int>{ -1, 1, 10, 100, 25, 9 }));
    CHECK(jsDefaultSort({ -10, -2, 3 }) == (std::vector<int>{ -10, -2, 3 }));
    CHECK(jsDefaultSort({}).empty());
}

